from __future__ import annotations

import ast
import json
import re
from typing import Any

import httpx

from .config import settings
from .models import CodeFileProposal, CodePlan, DeployVerificationPlan, RepairPlan


class DeepSeekClient:
    def __init__(self) -> None:
        self._api_key = settings.deepseek_api_key
        self._base_url = settings.deepseek_base_url.rstrip("/")
        self._model = settings.deepseek_model

    def _fallback_code_plan(self, task: str) -> CodePlan:
        content = (
            "# Auto-generated draft\n\n"
            f"Task: {task}\n\n"
            "This file was generated by fallback logic because DeepSeek API key is missing."
        )
        return CodePlan(
            summary="Fallback plan generated without DeepSeek API.",
            files=[CodeFileProposal(path="AUTO_GENERATED_TASK.md", content=content)],
            local_commands=[],
        )

    async def _chat(self, system_prompt: str, user_prompt: str) -> str:
        if not self._api_key:
            return ""

        payload = {
            "model": self._model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "temperature": 0.1,
            "response_format": {"type": "json_object"},
        }
        headers = {"Authorization": f"Bearer {self._api_key}", "Content-Type": "application/json"}
        async with httpx.AsyncClient(timeout=120) as client:
            response = await client.post(f"{self._base_url}/chat/completions", json=payload, headers=headers)
            response.raise_for_status()
            data = response.json()
            return data["choices"][0]["message"]["content"]

    def _parse_json_relaxed(self, raw: str) -> dict[str, Any] | None:
        if not raw:
            return None
        cleaned = raw.strip()
        cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned, flags=re.IGNORECASE)
        cleaned = re.sub(r"\s*```$", "", cleaned)
        try:
            return json.loads(cleaned)
        except Exception:
            pass
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start != -1 and end != -1 and end > start:
            snippet = cleaned[start : end + 1]
            try:
                return json.loads(snippet)
            except Exception:
                try:
                    # Some model outputs contain single quotes or python-like dicts.
                    parsed_any = ast.literal_eval(snippet)
                    if isinstance(parsed_any, dict):
                        return parsed_any
                except Exception:
                    return None
        return None

    def _validate_repair_plan_payload(self, parsed: dict[str, Any]) -> tuple[bool, str]:
        actions = parsed.get("actions")
        if not isinstance(actions, list) or not actions:
            return False, "actions must be a non-empty array"

        allowed = {
            "run_remote_command",
            "run_local_command",
            "replace_text_in_file",
            "ensure_postgres_db",
        }
        for idx, action in enumerate(actions):
            if not isinstance(action, dict):
                return False, f"actions[{idx}] must be an object"
            action_type = str(action.get("action_type", "")).strip().lower()
            if action_type not in allowed:
                return False, f"actions[{idx}].action_type is invalid"
            if action_type in {"run_remote_command", "run_local_command"} and not str(action.get("command", "")).strip():
                return False, f"actions[{idx}].command is required for {action_type}"
            if action_type == "run_local_command":
                cmd = str(action.get("command", "")).strip().lower()
                # In this orchestrator, repair loop targets deployed environment.
                # Local commands frequently create loops and should not be used.
                return False, f"actions[{idx}].run_local_command is not allowed in repair plans (use run_remote_command): {cmd}"
            if action_type == "replace_text_in_file":
                if not str(action.get("file_path", "")).strip():
                    return False, f"actions[{idx}].file_path is required for replace_text_in_file"
                if not str(action.get("find_text", "")).strip():
                    return False, f"actions[{idx}].find_text is required for replace_text_in_file"
                if "replace_text" not in action or action.get("replace_text") is None:
                    return False, f"actions[{idx}].replace_text is required for replace_text_in_file (string, use \"\" to delete find_text)"
                if str(action.get("find_text", "")).strip() == str(action.get("replace_text", "")).strip():
                    return False, f"actions[{idx}].find_text and replace_text must differ for replace_text_in_file"

        return True, ""

    async def build_code_plan(self, task_text: str, context_md: str) -> CodePlan:
        if not self._api_key:
            return self._fallback_code_plan(task_text)

        system_prompt = (
            "You are a senior software architect and Python engineer. "
            "Return strict JSON with keys: summary, files, local_commands. "
            "files is array of objects: {path, content}. "
            "Only produce relevant project files."
        )
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Context docs:\n{context_md}\n\n"
            "Generate implementation draft for a Python/FastAPI project."
        )
        raw = await self._chat(system_prompt, user_prompt)
        try:
            parsed: dict[str, Any] = json.loads(raw)
            return CodePlan(**parsed)
        except Exception:
            return self._fallback_code_plan(task_text)

    async def build_fix_code_plan(self, change_request: str, context_md: str) -> CodePlan:
        if not self._api_key:
            return CodePlan(
                summary="No DeepSeek API key; cannot build fix-only plan.",
                files=[],
                local_commands=[],
            )
        cap = settings.fix_only_max_plan_files
        system_prompt = settings.fix_only_plan_system_prompt
        user_prompt = (
            f"Change request (implement with minimal scope):\n{change_request}\n\n"
            f"Hard cap: at most {cap} objects in the files array.\n\n"
            f"Repository / contract context:\n{context_md[:55000]}\n\n"
            "Return JSON: summary, files (each with path and full content), local_commands."
        )
        raw = await self._chat(system_prompt, user_prompt)
        try:
            parsed: dict[str, Any] = json.loads(raw)
            plan = CodePlan(**parsed)
        except Exception:
            return CodePlan(
                summary="Failed to parse fix-only plan JSON.",
                files=[],
                local_commands=[],
            )
        plan.files = plan.files[:cap]
        return plan

    async def generate_file_content(
        self,
        task_text: str,
        context_md: str,
        file_path: str,
        generated_files_md: str,
        base_file_content: str,
        dependency_context_md: str = "",
        invariants_md: str = "",
        fix_only: bool = False,
    ) -> str:
        if not self._api_key:
            if base_file_content:
                return base_file_content
            return f"# Fallback content for {file_path}\n"

        if fix_only:
            system_prompt = (
                "You are applying a minimal patch to one file in an existing project. "
                "Return strict JSON with key: content. "
                "content must be the COMPLETE file after your edit. "
                "Touch only what the change request requires; keep imports, structure, formatting, and unrelated logic unchanged. "
                "Do not rename routes, env vars, or service identifiers unless the change request explicitly requires it. "
                "Preserve public API contracts (paths, JSON shapes) described in context unless the request mandates a breaking change."
            )
        else:
            system_prompt = (
                "You are a senior Python full-stack engineer. "
                "Return strict JSON with key: content. "
                "Generate code for a single file with path provided by user. "
                "Respect already generated files and keep API/import consistency."
            )
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Context docs:\n{context_md}\n\n"
            f"Hard invariants (must not be violated):\n{invariants_md}\n\n"
            f"Target file path:\n{file_path}\n\n"
            f"Current file content from repository (if exists):\n{base_file_content}\n\n"
            f"Dependency-aware retrieved context:\n{dependency_context_md}\n\n"
            f"Already generated key files:\n{generated_files_md}\n\n"
            + (
                "Apply the change request with minimal diff. Output the full file."
                if fix_only
                else "Generate final content for the target file. Keep consistency with dependencies and invariants."
            )
        )
        raw = await self._chat(system_prompt, user_prompt)
        try:
            parsed: dict[str, Any] = json.loads(raw)
            content = str(parsed.get("content", "")).strip()
            if content:
                return content + ("\n" if not content.endswith("\n") else "")
        except Exception:
            pass
        return base_file_content or f"# Empty content generated for {file_path}\n"

    async def build_architecture_spec(self, task_text: str, context_md: str, architect_prompt: str | None = None) -> str:
        if not self._api_key:
            return (
                "# Project context\n\n"
                "## Goal\n"
                f"{task_text}\n\n"
                "## Tech stack\n"
                "- Python 3.11\n- FastAPI\n- Docker\n\n"
                "## Functional requirements\n- Define core endpoints and expected behavior.\n\n"
                "## Non-functional requirements\n- Basic reliability and readability.\n\n"
                "## Project structure requirements\n- main application entrypoint and dependency file.\n\n"
                "## Run requirements\n- Containerized startup command.\n\n"
                "## Acceptance criteria\n- Main endpoint responds successfully."
            )

        system_prompt = architect_prompt.strip() if architect_prompt else settings.architect_system_prompt
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Context docs:\n{context_md}\n\n"
            "Generate architecture specification markdown for implementation."
        )
        raw = await self._chat(system_prompt, user_prompt)
        try:
            parsed: dict[str, Any] = json.loads(raw)
            spec = str(parsed.get("architecture_spec_markdown", "")).strip()
            if spec:
                return spec
        except Exception:
            pass
        return (
            "# Project context\n\n"
            "## Goal\n"
            f"{task_text}\n\n"
            "## Tech stack\n"
            "- Python 3.11\n- FastAPI\n- Docker\n\n"
            "## Functional requirements\n- Define required API and behavior.\n\n"
            "## Non-functional requirements\n- Stability and maintainability.\n\n"
            "## Project structure requirements\n- Clear project layout and dependencies.\n\n"
            "## Run requirements\n- Provide container startup flow.\n\n"
                "## Acceptance criteria\n- Main behavior works end-to-end.\n\n"
                "## Deploy verification (final stage)\n"
                "1. Preconditions: describe ports and URLs on 127.0.0.1 after compose.\n"
                "2. Run `docker compose ps` and expect all required services running.\n"
                "3. One smoke check appropriate to the app (e.g. curl a documented endpoint).\n"
                "4. Failure criteria: non-2xx HTTP or error signatures in logs.\n"
        )

    async def propose_deploy_verification_commands(
        self,
        task_text: str,
        architecture_spec: str,
        deploy_project_dir: str,
        runtime_gate_excerpt: str = "",
    ) -> DeployVerificationPlan:
        if not self._api_key:
            return DeployVerificationPlan(commands=[], rationale="No API key; skipping model-generated deploy verification.")

        system_prompt = (
            "You translate an approved architecture specification into executable remote verification. "
            "Return strict JSON only with keys: commands (array of strings), rationale (string). "
            f"commands must have at most {settings.deploy_verify_max_commands} entries. "
            "Each command is a single-line shell snippet run on the Linux deployment host over SSH. "
            "Prefer commands that assume the current directory will be prefixed with "
            f"`cd \\\"{deploy_project_dir}\\\" &&` by the orchestrator when the snippet does not already start with `cd `. "
            "Use docker compose, curl, wget, psql, etc. as appropriate to the stack described in the architecture. "
            "Do not use destructive operations (no rm -rf, no volume wipes, no mkfs). "
            "If the architecture's 'Deploy verification (final stage)' section is missing or too vague, infer minimal safe checks from Run requirements and Acceptance criteria. "
            "HARD RULES (ground truth only): "
            "(1) The first command in commands MUST be `docker compose ps` (with cd into the deploy directory as above). "
            "Service names and published HOST ports for curl/wget MUST be taken only from that compose reality plus what is explicitly written in the architecture/task "
            "(e.g. PORTS column `0.0.0.0:8086->80/tcp` means curl to `http://127.0.0.1:8086/...` on the deploy host). "
            "Never invent ports such as 3000, 8080, or 5000 unless they literally appear in the architecture text or in the docker compose ps / compose file described there. "
            "(2) HTTP paths for smoke checks MUST match API routes that are explicitly documented in the architecture markdown OR clearly named in the business task "
            "(path literals, OpenAPI fragment, or 'Deploy verification' curl examples). "
            "Do NOT assume a `/api/` prefix, `/api/tasks`, or generic SPA dev ports—if routes are not stated, use only compose ps, compose logs, and non-HTTP checks "
            "until a path is justified by the spec. "
            "(3) For `docker compose exec SERVICE curl http://localhost:PORT/...`, PORT must match how that SERVICE listens inside its container per architecture / "
            "typical mapping in the spec (e.g. FastAPI uvicorn 8000)—never guess 3000 for a Python API container. "
            "Do not use `docker compose exec SERVICE` for a SERVICE that is not in `Up` state in RUNTIME_GATE_CAPTURE (compose ps step; use host-side curl to published ports, "
            "or fix-oriented compose logs instead). Prefer `curl -fsS` on the deploy host to `http://127.0.0.1:<host_port>` from the PORTS column; "
            "do not assume `wget` exists inside application containers unless the architecture or Dockerfile excerpt says so. "
            "(4) You may include `docker compose config --services` after ps; still no invented topology. "
            "(5) If RUNTIME_GATE_CAPTURE is present in the user message, treat it as authoritative ground truth from the server: "
            "host port bindings and STATUS from the compose ps step, plus recent compose logs and any analyzer summary in that block. "
            "Your verification commands must be consistent with that capture (do not invent ports or ignore visible errors)."
        )
        gate_block = (runtime_gate_excerpt or "").strip()
        gate_section = (
            "\n\n### RUNTIME_GATE_CAPTURE (full output of orchestrator pre-verify checks: docker compose ps -a, compose logs tail, log gate)\n"
            f"```\n{gate_block[:24000]}\n```\n"
            if gate_block
            else ""
        )
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Deploy directory on server (project root):\n{deploy_project_dir}\n\n"
            f"Approved architecture specification (markdown):\n{architecture_spec[:60000]}\n"
            f"{gate_section}\n"
            "Produce commands that prove the deployment works after docker compose up. "
            "Anchor every curl URL to (a) host ports and service names from RUNTIME_GATE_CAPTURE / your first `docker compose ps` step and "
            "(b) HTTP paths that you can quote from the task or architecture above—no guessed frameworks."
        )
        raw = await self._chat(system_prompt, user_prompt)
        parsed = self._parse_json_relaxed(raw)
        if not isinstance(parsed, dict):
            return DeployVerificationPlan(commands=[], rationale="Model returned invalid JSON for deploy verification.")
        cmds_raw = parsed.get("commands")
        if not isinstance(cmds_raw, list):
            return DeployVerificationPlan(commands=[], rationale="commands array missing or invalid.")
        out: list[str] = []
        for item in cmds_raw[: settings.deploy_verify_max_commands]:
            if isinstance(item, str) and item.strip():
                out.append(item.strip())
        rationale = str(parsed.get("rationale", "")).strip()
        return DeployVerificationPlan(commands=out, rationale=rationale)

    async def review_and_fix_hint(self, task_text: str, last_error: str, context_md: str) -> str:
        if not self._api_key:
            return "Fallback review: inspect deployment logs and ensure docker compose services are healthy."
        system_prompt = (
            "You are a strict code reviewer. Return JSON with key: fix_hint. "
            "Address the primary failure in last_error (e.g. nginx not starting, 404 route mismatch, compose ps showing a service not Up). "
            "Do not reduce the whole incident to a secondary tool missing (e.g. wget) unless last_error is only about that."
        )
        user_prompt = (
            f"Task:\n{task_text}\n\nLast deployment or test error:\n{last_error}\n\nContext:\n{context_md}"
        )
        raw = await self._chat(system_prompt, user_prompt)
        try:
            parsed = json.loads(raw)
            return str(parsed.get("fix_hint", "No fix hint provided."))
        except Exception:
            return "Failed to parse review response. Check logs and deployment steps."

    async def propose_repair_discovery_commands(
        self,
        task_text: str,
        last_error: str,
        runtime_facts: str,
    ) -> list[str]:
        """Model-chosen read-only SSH steps before a repair plan (generic, not error-specific)."""
        if not self._api_key:
            return []
        system_prompt = (
            "You are a senior SRE debugging a failed deploy or validation step. "
            "Return strict JSON only: { \"commands\": string[], \"rationale\": string }. "
            "commands has at most 5 entries; each is one line run on the deployment host over SSH (read-only). "
            "Purpose: gather facts that remove guesswork before anyone edits files. "
            "Allowed patterns: docker compose ps, docker compose logs, docker compose config, "
            "docker compose exec SERVICE cat PATH, curl -sS -D- (no body dump of huge binaries), nginx -t, ls, test -f. "
            "Forbidden: modifying files, git write, docker compose down, rm, volume wipes, redirects that overwrite files, kubectl delete. "
            "If runtime_facts (compose ps, logs) already pin the root cause, return commands: [] and explain in rationale. "
            "When using docker compose from a project checkout, prefix with cd to that directory if the path appears in facts. "
            "If [compose_ps] shows a service is not Up (exited / missing from running table), do NOT propose docker compose exec into that service; "
            "read its config from the repo on the host (cat/grep paths under the deploy directory, e.g. frontend/nginx.conf) instead."
        )
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Primary error:\n{last_error}\n\n"
            f"Known runtime facts:\n{runtime_facts[:48000]}\n\n"
            "Propose a short diagnostic sequence (or empty if unnecessary). When one hypothesis is weak, add checks from another angle "
            "(reverse proxy vs app routes vs DB vs bind mounts vs wrong published port)."
        )
        raw = await self._chat(system_prompt, user_prompt)
        parsed = self._parse_json_relaxed(raw)
        if not isinstance(parsed, dict):
            return []
        cmds_raw = parsed.get("commands")
        if not isinstance(cmds_raw, list):
            return []
        out: list[str] = []
        forbidden = ("rm -rf", " mkfs", " dd ", "docker compose down", "git push", "git commit", "> /etc/", "> /dev/")
        for item in cmds_raw[:5]:
            if not isinstance(item, str):
                continue
            cmd = item.strip()
            if not cmd:
                continue
            lowered = cmd.lower()
            if any(bad in lowered for bad in forbidden):
                continue
            out.append(cmd)
        return out

    async def propose_repair_plan(
        self,
        task_text: str,
        last_error: str,
        context_md: str,
        runtime_facts: str,
    ) -> RepairPlan:
        if not self._api_key:
            return RepairPlan(
                diagnosis="Fallback repair plan without model.",
                confidence=0.2,
                actions=[],
                expected_outcome="No actions generated in fallback mode.",
                validation_steps=[],
            )

        system_prompt = (
            "You are the sole repair agent: you decide what is broken and how to fix it; no other layer invents patches for you. "
            "Return strict JSON only (no markdown). "
            "Required top-level keys: diagnosis(string), confidence(number 0..1), actions(array), expected_outcome(string), validation_steps(array of strings). "
            "Each action must include: action_type, target, command, file_path, find_text, replace_text, reason. "
            "Allowed action_type values: run_remote_command, run_local_command, replace_text_in_file, ensure_postgres_db. "
            "Do NOT use run_local_command in repair plans. "
            "Investigation mindset: form hypotheses from the Error and Runtime facts. If evidence is thin or prior fixes failed (see recent_repair_feedback), "
            "do NOT guess find_text for replace_text_in_file—use run_remote_command to disprove/confirm hypotheses (different angles: HTTP path vs reverse proxy vs "
            "app route vs DB vs bind mount vs wrong service). "
            "When MODEL_DIAGNOSTIC_CAPTURE appears in runtime facts, treat it as authoritative ground truth from the host; reconcile it with repository excerpts. "
            "replace_text_in_file: file_path relative to repo root; find_text MUST be copied verbatim from a repository file excerpt in runtime facts OR from "
            "MODEL_DIAGNOSTIC_CAPTURE only when that capture clearly shows the same file content that exists in the repo (e.g. mounted config). "
            "Never paste imagined nginx/docker-compose snippets. "
            "Docker Compose rule: each host port (left side of host:container in ports:) must appear at most once in the file. "
            "If the error says a host port is mapped more than once, edit compose so only one service publishes that host port. "
            "Use 'docker compose' syntax (not docker-compose) when suggesting shell commands. "
            "Execution order (orchestrator): all replace_text_in_file run first; then git commit/push and server pull + compose rebuild (when auto_deploy); "
            "then run_remote_command / ensure_postgres_db in list order; then validation_steps. "
            "So remote commands after file edits see updated files on the server—schedule run_remote_command accordingly (e.g. rebuild after config change). "
            "recent_repair_feedback: failures in the current incident. If the same patch class failed repeatedly, switch strategy and cite new evidence. "
            "For run_remote_command, command MUST be non-empty and executable as-is. "
            "For replace_text_in_file, replace_text is the replacement substring (use empty string only when intentionally removing find_text). "
            "validation_steps: concrete shell snippets (quoted) to prove the fix. "
            "If compose_ps in runtime facts shows a service is not Up, validation_steps must NOT use docker compose exec into that service; "
            "use curl from the host to 127.0.0.1 and the host port from the PORTS column, or docker compose logs for that service. "
            "Host ports in validation_steps must match the PORTS column from compose_ps—never invent a port. "
            "Do not return empty actions unless no safe action exists."
        )
        user_prompt = (
            f"Business task:\n{task_text}\n\n"
            f"Error (primary signal):\n{last_error}\n\n"
            f"Runtime facts (includes compose excerpt and recent_repair_feedback when present):\n{runtime_facts}\n\n"
            f"Context docs:\n{context_md}\n\n"
            "Produce a repair plan whose actions you can defend: file edits must match the excerpt exactly; remote commands must be safe and minimal."
        )
        validation_feedback = ""
        for _ in range(3):
            prompt = user_prompt
            if validation_feedback:
                prompt += (
                    "\n\nPrevious response was rejected. Fix it and return JSON again.\n"
                    f"Validation error: {validation_feedback}\n"
                    "Return ONLY JSON object."
                )
            raw = await self._chat(system_prompt, prompt)
            parsed = self._parse_json_relaxed(raw)
            if parsed is None:
                validation_feedback = "invalid JSON format"
                continue
            valid, reason = self._validate_repair_plan_payload(parsed)
            if not valid:
                validation_feedback = reason
                continue
            try:
                return RepairPlan(**parsed)
            except Exception as exc:
                validation_feedback = f"schema validation failed: {exc}"
                continue
        return RepairPlan(
            diagnosis=f"Failed to build valid repair plan JSON. {validation_feedback or 'Unknown parsing issue.'}",
            confidence=0.1,
            actions=[],
            expected_outcome="No executable repair actions.",
            validation_steps=[],
        )
